export type ErrorDetailInput = { /** API key modes in which this scope may be granted. */ "allowed_key_modes"?: Array<"live" | "test">; /** Whole-number quantity currently available for the requested operation; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "available_quantity"?: string; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "blocking_resource_count"?: string; /** Bounded resources that must transition or be corrected before the operation can succeed. */ "blocking_resources"?: Array<ErrorResourceReferenceInput>; /** Flint capability associated with this error, when applicable. */ "capability"?: string; "capturable_money"?: MoneyValueInput; /** Physical revision captured when the inventory count started. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 0. */ "captured_physical_revision"?: string; "code": string; "conflict_type"?: "physical_revision" | "source_observation_sequence"; "conflicting_fields"?: Array<string>; "current_checkout_session_id"?: string; /** Current money amount counted toward the threshold, when the error is threshold-based. */ "current_money"?: { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** Current physical revision observed when applying the inventory count. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 0. */ "current_physical_revision"?: string; /** Current fulfillment, shipment, or package returned when a conditional write conflicts with resource state. */ "current_resource"?: (({ /** Current hold details. While this field is present, status continues to show the public work status from before the hold. */ "active_hold"?: never; "charges"?: never; /** Completion evidence timestamp. Format: date-time. */ "completed_at"?: string | globalThis.Date; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: never; "customer_id"?: string; "device_id"?: string; "digital_details"?: DigitalFulfillmentDetailsInput; /** First time this fulfillment reached dispatched. Format: date-time. */ "dispatched_at"?: never; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; "fulfillment_id"?: never; "line_items": Array<FulfillmentLineItemInput>; "local_delivery_details"?: DeliveryFulfillmentDetailsInput; "location_id"?: string; "metadata"?: Record<string, string>; "order"?: never; "order_id"?: never; /** Terminal outcome details. The mark_no_show action records its reason here and returns status as failed. */ "outcome"?: never; "packages"?: never; /** First time this fulfillment reached packed. Format: date-time. */ "packed_at"?: never; /** First time this fulfillment reached picked. Format: date-time. */ "picked_at"?: never; "pickup_details"?: PickupFulfillmentDetailsInput; /** Read-only current quantity accounting behavior for this fulfillment state. */ "quantity_effect"?: never; "recipient"?: FulfillmentRecipientInput; /** Provider acceptance state, independent from fulfillment work progress. The accept action sets this field to accepted while status remains pending. */ "request_status"?: never; "service_details"?: ServiceFulfillmentDetailsInput; "shipments"?: never; /** Public work status. Fulfillments with request_status accepted project to status pending. Fulfillments with outcome.outcome_type no_show project to status failed. A fulfillment with active_hold projects to its public work status from before the hold. - `pending`: Work has not started. Start, schedule, accept, hold, cancel, or fail it as supported_actions allows. - `in_progress`: Work has started and is not yet ready or complete. - `ready`: The fulfillment is ready for pickup, handoff, or completion. - `completed`: All fulfillment work completed successfully. - `canceled`: The fulfillment was intentionally canceled and will not continue. - `failed`: The fulfillment could not be completed. Resolve the recorded reason before creating replacement work. - `scheduled`: The fulfillment is scheduled for its recorded service window. - `preparing`: Warehouse or provider preparation is underway. - `picked`: The assigned items have been picked. - `packed`: The assigned items have been packed. - `dispatched`: The fulfillment left its origin for delivery or handoff. */ "status"?: never; /** Read-only actions currently supported for this fulfillment. */ "supported_actions"?: never; /** When the fulfillment entered a terminal state: completed, canceled, or failed. This records the state transition; completed_at records completion evidence supplied for the fulfillment. Format: date-time. */ "terminal_at"?: never; "type": "shipment" | "pickup" | "local_delivery" | "digital" | "service"; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: never; /** Monotonic fulfillment version for expected_version checks. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 1. */ "version"?: never; }) | ({ /** Creation timestamp. Format: date-time. */ "created_at"?: never; /** RFC3339 timestamp. Format: date-time. */ "delivered_at"?: never; "direction"?: never; /** Caller-owned identifier for this resource in an external system. Caller-owned shipment identifier in external_system. Set with external_system to enable duplicate detection and replay for that provider reference. maxLength: 255. */ "external_reference_id"?: string; /** External carrier, aggregator, or fulfillment platform name for this shipment. Set with external_reference_id to enable duplicate detection and replay for that provider reference; without external_reference_id this is stored as provenance only. */ "external_system"?: string; "fulfillment_id"?: never; /** Carrier acceptance timestamp. For return shipments, this can satisfy an after_handoff execution gate for the declared return_line_items. Format: date-time. */ "handed_off_at"?: never; "metadata"?: Record<string, string>; "order"?: never; "order_id"?: never; /** Total number of packages attached to the shipment, including voided packages. Format: int32. minimum: 0. */ "package_count"?: never; "return_id"?: string; "return_line_items"?: Array<ReturnShipmentLineItemAllocationInput>; "shipment_id"?: never; /** RFC3339 timestamp. Format: date-time. */ "shipped_at"?: never; /** Read-only shipment state derived from the shipment's package states. An empty shipment remains a created draft. - `created`: The shipment leg exists but has not been packed or handed off. - `packed`: The shipment leg is packed and awaiting carrier handoff. - `shipped`: The shipment leg was handed to the carrier. - `in_transit`: The carrier is moving the shipment through its network. - `out_for_delivery`: The shipment is on its final delivery route. - `delivered`: The carrier reported successful delivery. - `delivery_attempted`: The carrier attempted delivery but did not complete it. Follow the carrier instructions before retrying delivery. - `exception`: A carrier exception is blocking normal progress. Resolve the carrier-reported issue. - `returned`: The shipment was returned toward or to its origin. - `voided`: The shipment was voided and will not continue through delivery. */ "status"?: never; /** Last update timestamp. Format: date-time. */ "updated_at"?: never; /** Monotonic shipment version for expected_version checks. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 1. */ "version"?: never; }) | ({ "carrier"?: string; /** Creation timestamp. Format: date-time. */ "created_at"?: never; /** Package delivery timestamp. Format: date-time. */ "delivered_at"?: never; "dimensions"?: ShippingDimensionsInput; /** Caller-owned identifier for this resource in an external system. Caller-owned package identifier in external_system. Set with external_system to enable duplicate detection and replay for that provider reference. maxLength: 255. */ "external_reference_id"?: string; /** External carrier, aggregator, or fulfillment platform name for this package. Set with external_reference_id to enable duplicate detection and replay for that provider reference; without external_reference_id this is stored as provenance only. */ "external_system"?: string; "fulfillment_id"?: never; /** Merchant or integration supplied HTTPS shipping-label URL for authenticated merchant workflows. Non-Flint URLs must include external_system for provenance. Flint does not currently manage label file hosting or buyer-facing label downloads. */ "label_url"?: string; "metadata"?: Record<string, string>; "order"?: never; "order_id"?: never; "package_id"?: never; /** Return this package belongs to. Present only on packages of return shipments. */ "return_id"?: never; /** Return line quantities allocated to this parcel. Present only on packages of return shipments. */ "return_line_items"?: never; "service_code"?: string; "shipment_id"?: never; /** Package handoff timestamp. Format: date-time. */ "shipped_at"?: never; /** Current package lifecycle state. Package states are the source used to derive shipment status. - `created`: The package record exists but has not been packed or handed off. - `packed`: The package is packed and awaiting carrier handoff. - `shipped`: The package was handed to the carrier. - `in_transit`: The carrier is moving the package through its network. - `out_for_delivery`: The package is on its final delivery route. - `delivered`: The carrier reported successful delivery. - `delivery_attempted`: The carrier attempted delivery but did not complete it. Follow the carrier instructions before retrying delivery. - `exception`: A carrier exception is blocking normal progress. Resolve the carrier-reported issue. - `returned`: The package was returned toward or to its origin. - `voided`: The package was voided and will not continue through delivery. */ "status"?: never; "status_reason"?: string; /** Read-only actions currently supported for this package. */ "supported_actions"?: never; "tracking_number"?: string; /** Absolute HTTPS carrier tracking URL. Embedded URL credentials are rejected. */ "tracking_url"?: string; /** Last update timestamp. Format: date-time. */ "updated_at"?: never; /** Monotonic package version for expected_version checks. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 1. */ "version"?: never; "weight"?: ShippingWeightInput; })); /** Current effective delivery selection ID returned with a selection concurrency conflict. */ "current_selection_id"?: string; /** Latest accepted absolute source sequence for this item and Location. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 0. */ "current_source_observation_sequence"?: string; /** Current lifecycle status of the resource when the requested mutation is not allowed. */ "current_status"?: string; /** Current mutable resource version observed when a conditional mutation failed. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 0. */ "current_version"?: string; "demand_key"?: string; /** Stable dependency category blocking a Location lifecycle transition. */ "dependency_type"?: "devices" | "fulfillment" | "inventory_allocation_policies" | "inventory_capability" | "inventory_claims" | "inventory_counts" | "inventory_levels" | "inventory_transfers" | "settings"; "eligibility_reason"?: "location_not_active" | "inventory_not_configured" | "inventory_allocation_inactive" | "outside_policy" | "outside_allowed_set" | "destination_missing" | "geography_unavailable" | "item_unavailable" | "forced_location_mismatch" | "fulfillment_incompatible" | "split_prohibited" | "insufficient_quantity"; "existing_checkout_session_id"?: string; "expected_attempt_outstanding_money"?: MoneyValueInput; /** Additional money amount needed to satisfy the threshold, when the error is threshold-based. */ "gap_money"?: { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; "inventory_count_line_id"?: string; "inventory_item_id"?: string; /** Whether the order payment attempt identified by payment_attempt_id can be resumed. If false, inspect payment_attempt_status before starting another payment. */ "is_resumable"?: boolean; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "limit"?: string; "location_id"?: string; "location_outcome"?: string; /** Maximum money amount accepted by the failed validation, calculated from the current resource state. */ "maximum_money"?: { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; "message": string; "param"?: string; "payment_attempt_id"?: string; /** Current Flint order payment attempt status associated with this error. */ "payment_attempt_status"?: "open" | "requires_action" | "processing" | "requires_capture" | "requires_retry" | "finalizing" | "partially_succeeded" | "succeeded" | "failed" | "canceled" | "expired"; "payment_intent_ids"?: Array<string>; "payment_method_domain_id"?: string; /** Flint payment option associated with this error, when the error is about a specific requested or selected payment option. */ "payment_option"?: "card" | "apple_pay" | "google_pay" | "affirm" | "ach_debit"; /** Structured resource quota state when the error is caused by quota exhaustion. */ "quota"?: { /** Maximum bytes available for the resource in the authenticated scope. Use an exact numeric string, not a floating-point number. Format: int64. */ "limit_bytes": string; /** RFC 3339 time when the next ready unattached image becomes eligible for cleanup, when known. Format: date-time. */ "next_expiration_at"?: string | globalThis.Date; /** Stored bytes held by completed images that are not attached to a resource. Use an exact numeric string, not a floating-point number. Format: int64. */ "ready_unattached_bytes": string; /** Bytes reserved by in-progress resource mutations. Use an exact numeric string, not a floating-point number. Format: int64. */ "reserved_bytes": string; /** Stable resource name whose quota was exhausted. */ "resource": string; /** Bytes currently stored for the resource in the authenticated scope. Use an exact numeric string, not a floating-point number. Format: int64. */ "used_bytes": string; }; /** Stable Flint reason code associated with this error. For payment option availability errors this matches PaymentOptionBlocker.code. When code is PROMOTION_DECLINED, branch on reason. Promotion decline reasons are: not_eligible, minimum_not_met, expired, not_yet_started, exhausted, code_required, code_invalid, disabled, automatic_disabled, codes_disabled, already_applied, not_combinable, superseded_by_better_offer, superseded, max_promotions_reached, no_discountable_balance, buy_item_missing, currency_mismatch, unknown_type. */ "reason"?: string; "remediation"?: ErrorRemediationInput; /** API key mode requested for the rejected scope grant. */ "requested_key_mode"?: "live" | "test"; /** Whole-number quantity submitted by the caller when a quantity-bearing operation conflicts with current capacity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "requested_quantity"?: string; /** Money amount required to satisfy a minimum threshold, when the error is threshold-based. */ "required_money"?: { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; "risk_rule_ids"?: Array<string>; /** Canonical public scope rejected by validation, when the detail concerns one scope. */ "scope"?: string; "selectable_payment_intents"?: Array<SelectableOrderPaymentIntentInput>; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "shortage_quantity"?: string; "submitted_money"?: MoneyValueInput; /** Absolute source sequence submitted for this inventory count line. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 0. */ "submitted_source_observation_sequence"?: string; /** Concrete corrective actions for this validation error. */ "suggestions"?: Array<string>; /** Actions accepted for the current resource state. */ "supported_actions"?: Array<string>; "supported_api_versions"?: Array<string>; "tip_capable_money"?: MoneyValueInput; };
